<?php
require_once __DIR__ . '/../../app/auth.php';
require_once __DIR__ . '/../../app/view.php';
require_once __DIR__ . '/../../app/discipline.php';
$db = database(); $user = workspace_user($db); $viewer = viewer_identity($user); $companyId = $viewer['company_id'];
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    require_post();
    rate_limit($db,'discipline-action',$viewer['role'] . ':' . $viewer['id'],60);
    $action = input('action'); $id = (int)input('id');
    $messages = [
        'issue'=>'You issued a query. Each selected person has a private query record and has been notified.',
        'respond'=>'Your response was sent.',
        'decide'=>'Decision recorded.',
        'propose'=>$viewer['role'] === 'admin' ? 'Penalty recorded and the person was notified.' : 'Penalty proposed. The workspace owner will review it.',
        'penalty_decision'=>'Penalty decision recorded.',
        'handoff_assign'=>'Penalty sent to the assigned staff member.',
        'handoff_forward'=>'Penalty forwarded to the next staff member.',
        'handoff_complete'=>'Penalty handoff marked complete.',
        'acknowledge'=>'Thank you. Your acknowledgement was recorded.',
        'appeal'=>'Your appeal was sent to the workspace owner.',
        'appeal_decision'=>'Appeal decision recorded.',
    ];
    if (!isset($messages[$action])) fail('Choose a valid action.',422);
    $queryId = $id;
    if (in_array($action,['penalty_decision','handoff_assign','handoff_forward','handoff_complete','acknowledge','appeal','appeal_decision'],true)) {
        $penalty = db_one($db,'SELECT query_id FROM penalties WHERE id = ? AND company_id = ?',[$id,$companyId]);
        if (!$penalty) fail('This penalty could not be found in your workspace.',404);
        $queryId = (int)$penalty['query_id'];
    }
    switch ($action) {
        case 'issue': $queryId = issue_query($db,$viewer,$_POST); break;
        case 'respond': respond_to_query($db,$viewer,$id,(string)($_POST['response'] ?? '')); break;
        case 'decide': decide_query($db,$viewer,$id,input('outcome'),input('note')); break;
        case 'propose': propose_penalty($db,$viewer,$id,$_POST); break;
        case 'penalty_decision': decide_penalty($db,$viewer,$id,input('decision'),input('note')); break;
        case 'handoff_assign': route_penalty_handoff($db,$viewer,$id,'assign',$_POST); break;
        case 'handoff_forward': route_penalty_handoff($db,$viewer,$id,'forward',$_POST); break;
        case 'handoff_complete': route_penalty_handoff($db,$viewer,$id,'complete',$_POST); break;
        case 'acknowledge': acknowledge_penalty($db,$viewer,$id); break;
        case 'appeal': appeal_penalty($db,$viewer,$id,(string)($_POST['appeal'] ?? '')); break;
        case 'appeal_decision': decide_appeal($db,$viewer,$id,input('outcome'),input('note'),input('new_type'),input('new_amount')); break;
    }
    flash($messages[$action]);
    redirect(query_url($queryId));
}
$settings = discipline_settings($db,$companyId);
if (($_GET['action'] ?? '') === 'new') {
    $taskId = (int)($_GET['task'] ?? 0); $projectId = (int)($_GET['project'] ?? 0);
    if ($taskId && $projectId) fail('Choose either a task or a project query.',422);
    $candidates = $projectId ? project_query_candidates($db,$viewer,$projectId) : query_candidates($db,$viewer);
    if (!$candidates) fail($viewer['role'] === 'admin' ? 'Add people to your workspace before issuing a query.' : 'Only the workspace owner and managers with direct reports can issue queries.',403);
    $task = null; $project = null; $facts = '';
    $presets = []; $taskSubject = '';
    if ($taskId) {
        [$task,$facts,$assigneeId] = task_facts($db,$viewer,$taskId);
        $taskSubject = 'employee:' . $assigneeId;
        if (!isset($candidates[$taskSubject])) fail('You are not authorised to query this task’s assignee.',403);
        $presets[] = $taskSubject;
    } elseif ($projectId) {
        [$project,$facts] = project_facts($db,$companyId,$projectId);
        $presets = array_keys($candidates);
    }
    if (is_string($_GET['subject'] ?? null) && isset($candidates[$_GET['subject']])) {
        if ($taskSubject !== '' && $_GET['subject'] !== $taskSubject) fail('A task query must be addressed to that task’s assigned employee.',403);
        $presets = [$_GET['subject']];
    }
    $presetSet = array_fill_keys($presets,true);
    suite_start('Issue a query','queries',$user);
    ?>
