<div class="page-heading"><div><h1>Issue a query</h1><p>Ask someone to explain, in writing, within a set time. They are notified in Simplr and by email, and the record is kept for your HR file.</p></div></div>
<section class="panel"><div class="panel-body"><form method="post" class="form-stack record-form" data-submit><?= csrf_field() ?><input type="hidden" name="action" value="issue"><?php if ($task): ?><input type="hidden" name="task_id" value="<?= (int)$task['id'] ?>"><div class="query-facts"><span class="badge <?= $task['due_date'] && $task['due_date'] < date('Y-m-d') && $task['status'] !== 'completed' ? 'overdue' : '' ?>">About a task</span><div class="rich-text"><?= rich_text_html($facts) ?></div></div><?php elseif ($project): ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><div class="query-facts"><span class="badge">About a project</span><div class="rich-text"><?= rich_text_html($facts) ?></div><small>Each selected person receives an individual query. Their responses are private to them and the authorised reviewers.</small></div><?php endif; ?>
<fieldset class="recipient-picker"><legend>Who should respond?</legend><?php if ($project): ?><label class="choice select-all-choice"><input type="checkbox" data-select-all-recipients<?= count($presetSet) === count($candidates) ? ' checked' : '' ?>><span><strong>Select the whole eligible project team</strong><small>Issues a separate query to each person listed below.</small></span></label><?php endif; ?><div class="recipient-options"><?php foreach ($candidates as $value=>$label): ?><label class="choice"><input type="checkbox" name="subjects[]" value="<?= e($value) ?>"<?= isset($presetSet[$value]) ? ' checked' : '' ?>><span><?= e($label) ?></span></label><?php endforeach; ?></div><?php if ($viewer['role'] === 'manager'): ?><small>You can query your direct reports. Project members outside your reporting line are not selectable.</small><?php endif; ?></fieldset>
<div class="field"><label for="query-title">Subject</label><input id="query-title" name="title" maxlength="200" required value="<?= $task ? e('Explanation required: ' . mb_strimwidth($task['title'],0,150,'…')) : '' ?>"></div>
<div class="field"><label for="query-message">Message *</label><textarea id="query-message" name="message" data-rich maxlength="10000" required placeholder="Describe what happened and what you need them to explain."><?= $task ? e('<p>The task above was not delivered as agreed. Please explain in writing why it was not completed on time, and what you will do to complete it.</p>') : '' ?></textarea></div>
<div class="field"><label for="query-window">Response window</label><select id="query-window" name="respond_minutes"><?php foreach ([1=>'1 minute',5=>'5 minutes',10=>'10 minutes',15=>'15 minutes',30=>'30 minutes',45=>'45 minutes',60=>'1 hour',120=>'2 hours',240=>'4 hours',480=>'8 hours',1440=>'1 day',4320=>'3 days',10080=>'7 days',20160=>'14 days'] as $minutes=>$label): ?><option value="<?= $minutes ?>"<?= $minutes === $settings['response_minutes'] ? ' selected' : '' ?>><?= e($label) ?><?= $minutes === $settings['response_minutes'] ? ' (workspace default)' : '' ?></option><?php endforeach; ?></select><small>Choose as little as one minute. After the deadline, the query is marked “No response” for review; no penalty happens automatically.</small></div>
<div class="form-actions"><button class="button" type="submit"><?= icon('flag') ?> Issue query</button><a class="button secondary" href="/users/admin/queries.php">Cancel</a></div></form></div></section>
<?php if ($project): ?><script>document.querySelector('[data-select-all-recipients]')?.addEventListener('change',event=>document.querySelectorAll('.recipient-options input[name="subjects[]"]').forEach(input=>input.checked=event.target.checked));document.querySelectorAll('.recipient-options input[name="subjects[]"]').forEach(input=>input.addEventListener('change',()=>{const all=[...document.querySelectorAll('.recipient-options input[name="subjects[]"]')];document.querySelector('[data-select-all-recipients]').checked=all.every(item=>item.checked)}));</script><?php endif; ?>
<?php suite_end(); exit; }
$query = db_one($db,'SELECT * FROM task_queries WHERE id = ? AND company_id = ?',[(int)($_GET['id'] ?? 0),$companyId]);
if (!$query || !can_view_discipline($db,$viewer,$query)) fail('This query could not be found in your workspace.',404);
$penalties = db_rows($db,'SELECT * FROM penalties WHERE company_id = ? AND query_id = ? ORDER BY id DESC',[$companyId,(int)$query['id']]);
$subjectName = person_name($db,$companyId,$query['subject_role'],(int)$query['subject_id']);
$issuerName = $query['issued_by_role'] === 'admin' ? 'Workspace owner' : person_name($db,$companyId,$query['issued_by_role'],(int)$query['issued_by_id']);
$company = db_one($db,'SELECT company_name FROM users WHERE company_id = ? ORDER BY id LIMIT 1',[$companyId])['company_name'] ?? '';
$canDecide = $viewer['role'] === 'admin' || is_issuer($viewer,$query);
$isSubject = is_subject($viewer,$query);
[$dueLabel,$dueTone] = discipline_due_label($query['respond_by']);
$currency = (string)(workspace_settings($db,$companyId)['currency'] ?? '');
$hasOpenPenalty = (bool)array_filter($penalties,fn($penalty)=>in_array($penalty['status'],['proposed','active'],true));
$handoffCandidates = penalty_handoff_candidates($db,$companyId);
$queryStatus = query_response_overdue($query) ? 'no_response' : $query['status'];
suite_start('Query ' . $query['reference'],'queries',$user);
?>
<a class="text-link back-crumb no-print" href="/users/admin/queries.php">← Queries &amp; penalties</a>
<div class="page-heading"><div><h1><?= e($query['title']) ?></h1><p><?= e($query['reference']) ?> · <span class="badge <?= e(stage_class($queryStatus)) ?>"><?= e(query_statuses()[$queryStatus] ?? $queryStatus) ?></span><?php if ($queryStatus === 'awaiting_response'): ?> · <span class="due <?= e($dueTone) ?>"><?= e($dueLabel) ?></span><?php endif; ?></p></div><button type="button" class="button secondary small no-print" onclick="window.print()"><?= icon('download') ?> Print or save as PDF</button></div>
