<?php if ($query['facts'] !== ''): ?><section class="query-facts"><span class="badge"><?= $query['project_id'] ? 'The project in question' : 'The task in question' ?></span><div class="rich-text"><?= rich_text_html($query['facts']) ?></div><?php if ($query['task_id'] && $viewer['role'] === 'admin'): ?><a class="text-link no-print" href="/users/admin/workspace.php?module=tasks&amp;action=view&amp;id=<?= (int)$query['task_id'] ?>">Open task <?= icon('arrow') ?></a><?php elseif ($query['project_id'] && $viewer['role'] === 'admin'): ?><a class="text-link no-print" href="/users/admin/workspace.php?module=projects&amp;action=view&amp;id=<?= (int)$query['project_id'] ?>">Open project <?= icon('arrow') ?></a><?php endif; ?></section><?php endif; ?>
