<?php elseif ($isSubject && in_array($query['status'],['awaiting_response','no_response'],true)): ?><form method="post" class="form-stack no-print" data-submit><?= csrf_field() ?><input type="hidden" name="action" value="respond"><input type="hidden" name="id" value="<?= (int)$query['id'] ?>"><div class="field"><label for="query-response">Your response *</label><textarea id="query-response" name="response" data-rich maxlength="10000" required placeholder="Explain what happened, honestly and specifically."></textarea></div><button class="button" type="submit">Send response</button></form>
<?php else: ?><p class="subtle"><?= $queryStatus === 'no_response' ? 'No response was received within the response window.' : ($queryStatus === 'withdrawn' ? 'The query was withdrawn before a response.' : 'Waiting for a response.') ?></p><?php endif; ?></section>
