<?php if ($canDecide && in_array($queryStatus,['answered','no_response','escalated'],true) && !$hasOpenPenalty): ?><section class="panel no-print"><div class="panel-head"><h2><?= $viewer['role'] === 'admin' ? 'Record a penalty' : 'Propose a penalty' ?></h2><span class="count-label"><?= $viewer['role'] === 'admin' ? 'Approved when recorded' : 'The workspace owner approves penalties' ?></span></div><div class="panel-body"><form method="post" class="form-stack penalty-form" data-submit data-penalty-form><?= csrf_field() ?><input type="hidden" name="action" value="propose"><input type="hidden" name="id" value="<?= (int)$query['id'] ?>"><div class="access-grid"><div class="field"><label for="penalty-type">Penalty</label><select id="penalty-type" name="penalty_type" required data-penalty-type><?php foreach (penalty_types() as $value=>$label): ?><option value="<?= e($value) ?>"><?= e($label) ?></option><?php endforeach; ?></select></div><div class="field" data-show-for="deduction" hidden><label for="penalty-amount">Amount to record<?= $currency !== '' ? ' (' . e($currency) . ')' : '' ?></label><input id="penalty-amount" name="amount" inputmode="decimal" placeholder="0.00"><small>Recorded for payroll. Simplr does not deduct or move money.</small></div><div class="field" data-show-for="suspension" hidden><label for="penalty-start">Suspension starts</label><input id="penalty-start" type="date" name="starts_on"></div><div class="field" data-show-for="suspension" hidden><label for="penalty-end">Suspension ends</label><input id="penalty-end" type="date" name="ends_on"></div></div><div class="field"><label for="penalty-reason">Reason *</label><textarea id="penalty-reason" name="reason" data-rich maxlength="5000" required></textarea></div><p class="notice info compact">Check that this penalty follows your employment contracts, handbook and the law before recording it. Warnings expire after <?= (int)$settings['expiry_months'] ?> months.</p><button class="button" type="submit"><?= $viewer['role'] === 'admin' ? 'Record penalty' : 'Propose penalty' ?></button></form></div></section><?php endif; ?>
