<?php elseif (!$handoffs && $viewer['role'] === 'admin'): ?><form method="post" class="form-stack no-print" data-submit><?= csrf_field() ?><input type="hidden" name="action" value="handoff_assign"><input type="hidden" name="id" value="<?= (int)$penalty['id'] ?>"><div class="access-grid"><div class="field"><label for="initial-function-<?= (int)$penalty['id'] ?>">First function</label><select id="initial-function-<?= (int)$penalty['id'] ?>" name="function" required><option value="hr">HR</option><option value="accounting">Accounting</option><option value="other">Other</option></select></div><div class="field"><label for="initial-assignee-<?= (int)$penalty['id'] ?>">Assign to</label><select id="initial-assignee-<?= (int)$penalty['id'] ?>" name="assignee" required><option value="">Select a staff member</option><?php foreach ($handoffCandidates as $candidate=>$candidateName): ?><option value="<?= e($candidate) ?>"><?= e($candidateName) ?></option><?php endforeach; ?></select></div></div><div class="field"><label for="initial-note-<?= (int)$penalty['id'] ?>">Handoff note</label><input id="initial-note-<?= (int)$penalty['id'] ?>" name="note" maxlength="1000"></div><button class="button secondary" type="submit">Send to HR, Accounting or another staff member</button></form>
<?php elseif ($pendingHandoff && !penalty_handoff_assignee($viewer,$pendingHandoff) && $viewer['role'] !== 'admin'): ?><p class="subtle">Awaiting action from <?= e(person_name($db,$companyId,$pendingHandoff['assignee_role'],(int)$pendingHandoff['assignee_id'])) ?> (<?= e(penalty_handoff_function_name($pendingHandoff['handoff_function'])) ?>).</p><?php elseif ($handoffs && !$pendingHandoff): ?><p class="subtle">The handoff is complete.</p><?php endif; ?></section><?php endif; ?>
<?php if ($viewer['role'] === 'admin' && $penalty['status'] === 'proposed'): ?><form method="post" class="form-stack no-print decision-form" data-submit><?= csrf_field() ?><input type="hidden" name="action" value="penalty_decision"><input type="hidden" name="id" value="<?= (int)$penalty['id'] ?>"><div class="field"><label for="penalty-note-<?= (int)$penalty['id'] ?>">Note (optional)</label><input id="penalty-note-<?= (int)$penalty['id'] ?>" name="note" maxlength="1000"></div><div class="form-actions"><button class="button" name="decision" value="approve" type="submit">Approve penalty</button><button class="button secondary" name="decision" value="reject" type="submit">Reject</button></div></form><?php endif; ?>
<?php if (is_subject($viewer,$penalty) && $penalty['status'] === 'active'): ?><div class="no-print subject-actions"><?php if (!$penalty['acknowledged_at']): ?><form method="post" data-submit><?= csrf_field() ?><input type="hidden" name="action" value="acknowledge"><input type="hidden" name="id" value="<?= (int)$penalty['id'] ?>"><button class="button" type="submit"><?= icon('check') ?> I have read this</button></form><?php endif; ?><?php if (!$penalty['appealed_at']): ?><details class="appeal-box"><summary class="button secondary">Appeal this penalty</summary><form method="post" class="form-stack" data-submit><?= csrf_field() ?><input type="hidden" name="action" value="appeal"><input type="hidden" name="id" value="<?= (int)$penalty['id'] ?>"><div class="field"><label for="appeal-<?= (int)$penalty['id'] ?>">Why should this be reviewed? *</label><textarea id="appeal-<?= (int)$penalty['id'] ?>" name="appeal" data-rich maxlength="5000" required></textarea></div><button class="button" type="submit">Send appeal</button><small class="subtle">You can appeal once. The workspace owner decides.</small></form></details><?php endif; ?></div><?php endif; ?>
<?php if ($viewer['role'] === 'admin' && $penalty['status'] === 'active' && $penalty['appealed_at'] && !$penalty['appeal_outcome']): ?><form method="post" class="form-stack no-print decision-form" data-submit data-penalty-form><?= csrf_field() ?><input type="hidden" name="action" value="appeal_decision"><input type="hidden" name="id" value="<?= (int)$penalty['id'] ?>"><h3>Decide the appeal</h3><div class="field"><label for="appeal-note-<?= (int)$penalty['id'] ?>">Explanation *</label><textarea id="appeal-note-<?= (int)$penalty['id'] ?>" name="note" maxlength="1000" required></textarea></div><div class="access-grid"><div class="field"><label for="appeal-type-<?= (int)$penalty['id'] ?>">If reducing, replace with</label><select id="appeal-type-<?= (int)$penalty['id'] ?>" name="new_type" data-penalty-type><?php foreach (penalty_types() as $value=>$label): ?><option value="<?= e($value) ?>"<?= $value === 'verbal_warning' ? ' selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="field" data-show-for="deduction" hidden><label for="appeal-amount-<?= (int)$penalty['id'] ?>">Reduced amount</label><input id="appeal-amount-<?= (int)$penalty['id'] ?>" name="new_amount" inputmode="decimal"></div></div><div class="form-actions"><button class="button secondary" name="outcome" value="upheld" type="submit">Uphold penalty</button><button class="button secondary" name="outcome" value="reduced" type="submit">Reduce</button><button class="button" name="outcome" value="withdrawn" type="submit">Withdraw penalty</button></div></form><?php endif; ?>
</div></section>
<?php endforeach; ?>
<?php suite_end(); ?>
